        self,
        name: str,
        catalog_type: str,
        description: str,
        parameters: Dict[str, str],
        tags: List[Dict[str, str]],
    ) -> Optional[DataCatalog]:
        if name in self.data_catalogs:
            return None
        data_catalog = DataCatalog(self, name, catalog_type, description, parameters, tags)
        self.data_catalogs[name] = data_catalog
        return data_catalog

    def get_data_catalog(self, name: str) -> Optional[Dict[str, Any]]:
        if name not in self.data_catalogs:
            return None
        dc = self.data_catalogs[name]
        return {
            "Name": dc.name,
            "Type": dc.type,
            "Description": dc.description,
            "Parameters": dc.parameters,
        }

    def list_data_catalogs(self) -> List[Dict[str, Any]]:
        return [
            {
                "CatalogName": dc.name,
                "Type": dc.type,
            }
            for dc in self.data_catalogs.values()
        ]


